param([Parameter(Mandatory=$true)][string]$RepositoryRoot,[Parameter(Mandatory=$true)][string]$BuildRoot)
$ErrorActionPreference='Stop';$root=(Resolve-Path -LiteralPath $RepositoryRoot).Path;$build=[IO.Path]::GetFullPath($BuildRoot)
if(Test-Path -LiteralPath $build){throw "Refusing to overwrite existing build directory: $build"};New-Item -ItemType Directory -Path $build|Out-Null
$vs='C:\Program Files (x86)\Microsoft Visual Studio\2022\BuildTools\Common7\Tools\VsDevCmd.bat';if(!(Test-Path -LiteralPath $vs)){throw "Required MSVC environment entry point missing: $vs"}
$names=@('bx_ntvdm_host_drive_policy.c','bx_ntvdm_host_namespace.c','bx_ntvdm_cpu_delta_abi.c','bx_ntvdm_cpu_result_v2.c','bx_ntvdm_cpu_state_abi.c','bx_ntvdm_exception_abi.c','bx_ntvdm_instruction_window_abi.c','bx_ntvdm_guest_range.c','bx_ntvdm_guest_write_abi.c','bx_ntvdm_multi_write_abi.c','bx_ntvdm_multi_write_transaction.c','bx_ntvdm_search_session.c','bx_ntvdm_search_result_v1.c','bx_ntvdm_search_plan_v1.c','bx_ntvdm_search_request_v1.c','bx_ntvdm_search_transaction_v1.c')
$src=$names|%{Join-Path $root ('src\bx-vdm\'+$_)};$src+=Join-Path $root 'tests\bx-vdm\bx_ntvdm_dem_direct_search_transaction_v1_test.c';$exe=Join-Path $build 't202-s4-dem-direct-search.exe'
$cmd='call "'+$vs+'" -arch=x64 -host_arch=x64 >nul && cl.exe /nologo /TC /std:c11 /W4 /WX /MT /I "'+(Join-Path $root 'src\bx-vdm')+'" /Fe:"'+$exe+'" '+($src -join ' ')+' /link ntdll.lib bcrypt.lib';&cmd.exe /d /s /c $cmd 2>&1|Tee-Object (Join-Path $build 'compile.log');if($LASTEXITCODE -ne 0){throw 'direct search compilation failed'};&$exe 2>&1|Tee-Object (Join-Path $build 'run.log');if($LASTEXITCODE -ne 0){throw "direct search probe failed: $LASTEXITCODE"};Write-Host "T202 S4 direct-search probe passed: $build"
